//@ts-check

import { delegatesCacheInstance } from '../core/delegatesCache/DelegatesCache.js'
import { Interpreter } from '../core/interpreter/Interpreter.js'
import { Command } from '../utils/Command.js'
import { CommandType } from '../utils/CommandType.js'
import { ExceptionThrower } from '../utils/exception/ExceptionThrower.js'
import { generateGUID } from '../utils/guid/generateGuid.js'
import { RuntimeName } from '../utils/RuntimeName.js'
import { TypesHandler } from '../utils/TypesHandler.js'
import { ComplexTypeResolver } from './tools/ComplexTypeResolver.js'
import { GetInstanceFieldHelper } from './tools/GetInstanceFieldHelper.js'
/**
 * @typedef {import('../types.d.ts').RuntimeName} RuntimeNameType
 * @typedef {import('../utils/connectionData/IConnectionData.js').IConnectionData} IConnectionData
 */

class AsyncLock {
    #queue = Promise.resolve()

    /**
     * @returns {Promise<() => void>}
     */
    async lock() {
        /** @type {() => void} */
        let release = () => {}
        const gate = new Promise((resolve) => {
            release = /** @type {() => void} */ (resolve)
        })

        const prev = this.#queue
        this.#queue = this.#queue.then(() => gate)
        await prev
        return release
    }
}

class InvocationContext {
    /** @type {string} */
    #runtimeContextId
    /** @type {RuntimeNameType} */
    #runtimeName
    /** @type {IConnectionData} */
    #connectionData
    /** @type {Command | null} */
    #currentCommand = null
    /** @type {Command | null} */
    #responseCommand = null
    /** @type {boolean} */
    #isExecuted = false
    /** @type {boolean} */
    #isStateless = false
    /** @type {string | null} */
    #guid = null
    /** Async materialization lock for cross-call coordination. */
    #materializationLock = new AsyncLock()
    // Static map holding contexts waiting for materialization (guid -> InvocationContext)
    static _invocationContexts = new Map()
    // Static map of already materialized reference commands (guid -> Command)
    static _materializedReferences = new Map()
    /** Cooperative lock for the shared registry (aligned with Python/Go map mutex). */
    static #registryLock = { locked: false }

    // connectionData
    set connectionData(value) {
        this.#connectionData = value
    }

    get connectionData() {
        return this.#connectionData
    }

    /**
     *
     * @param {string} runtimeContextId
     * @param {RuntimeNameType} runtimeName
     * @param {IConnectionData} connectionData
     * @param {Command | null} command
     * @param {boolean} isExecuted
     * @param {boolean} isStateless
     */
    constructor(
        runtimeContextId,
        runtimeName,
        connectionData,
        command,
        isExecuted = false,
        isStateless = false
    ) {
        this.#runtimeContextId = runtimeContextId
        this.#runtimeName = runtimeName
        this.#connectionData = connectionData
        this.#currentCommand = command
        this.#responseCommand = null
        this.#isExecuted = isExecuted
        this.#guid = generateGUID()
        this.#isStateless = isStateless
    }

    /**
     * @returns {string} guid of this InvocationContext
     */
    getGuid() {
        // @ts-ignore
        return this.#guid
    }

    /**
     * @param {Command} command
     * @returns {InvocationContext}
     */
    #createInstanceContext(command) {
        return this.#buildInvocationContext(command)
    }

    /**
     * @param {Command} command
     * @returns {InvocationContext}
     */
    #buildInvocationContext(command) {
        return new InvocationContext(
            this.#runtimeContextId,
            this.#runtimeName,
            this.#connectionData,
            this.#buildCommand(command),
            this.#isExecuted,
            this.#isStateless
        )
    }

    /**
     * @returns {Command|null}
     */
    getCurrentCommand() {
        return this.#currentCommand
    }

    /**
     * @returns {boolean}
     */
    isStateless() {
        return this.#isStateless
    }

    //destructor() {
    //    if (this.#currentCommand.commandType === CommandType.Reference) {
    //        this.#currentCommand = new Command(
    //            this.#runtimeName,
    //            CommandType.DestructReference,
    //            this.#currentCommand.payload
    //        );
    //        this.execute();
    //    }
    //}
    /**
     * Async iterator for InvocationContext arrays
     * Use: for await (const item of invocationContext) { ... }
     * @returns {AsyncGenerator<InvocationContext, void, unknown>}
     */
    async *[Symbol.asyncIterator]() {
        if (this.#currentCommand?.commandType !== CommandType.Reference) {
            throw new Error('Object is not iterable')
        }

        const sizeCtx = await this.getSize().execute()
        const arraySize = Number(sizeCtx.getValue())

        for (let position = 0; position < arraySize; position++) {
            yield this.getIndex(position)
        }
    }

    /**
     * Executes the current command.
     * Returns the InvocationContext after executing the command.
     * @param connectionData {IConnectionData | null}
     * @returns {Promise<InvocationContext> | InvocationContext}
     * @method
     */
    execute(connectionData = null) {
        if (connectionData !== null && typeof connectionData !== 'undefined') {
            this.#connectionData = connectionData
        }

        if (this.#currentCommand === null) {
            throw new Error('currentCommand is undefined in Invocation Context execute method')
        }

        if (this.#isStateless && this.#currentCommand.commandType !== CommandType.PassByValue) {
            return this
        }

        return this.#executeAsync()
    }

    /**
     * Executes the current command asynchronously and always returns a Promise.
     * @param connectionData {IConnectionData | null}
     * @returns {Promise<InvocationContext>}
     */
    async executeAsync(connectionData = null) {
        return this.execute(connectionData)
    }

    /**
     * @returns {Promise<InvocationContext>}
     */
    async #executeAsync() {
        if (this.#currentCommand === null) {
            throw new Error('currentCommand is undefined in Invocation Context execute method')
        }

        /** @type {Array<() => void>} */
        const releases = []
        try {
            if (!this.#isStateless) {
                const referencedContexts = this.#getReferencedMaterializationContexts(this.#currentCommand)
                for (const ctx of referencedContexts) {
                    releases.push(await ctx.#materializationLock.lock())
                }

                // Replace stale RegisterForUpdate nodes with already materialized references.
                this.#currentCommand = this.#materializeUpdatedReferences(this.#currentCommand)
            }

            // Execute command on interpreter
            this.#responseCommand = await Interpreter.execute(
                this.#runtimeContextId,
                this.#currentCommand,
                this.#connectionData
            )

            if (!this.#responseCommand) {
                throw new Error('responseCommand is undefined in Invocation Context execute method')
            }
            if (this.#responseCommand.commandType === CommandType.Exception) {
                const exception = ExceptionThrower.throwException(this.#responseCommand)
                throw exception
            }

            if (this.#currentCommand.commandType === CommandType.CreateClassInstance) {
                this.#currentCommand = this.#responseCommand
                this.#isExecuted = true
                return this
            }

            // Always strip ValueForUpdate from payload; materialize instances only when stateful.
            this.#responseCommand = this.#processUpdateInvocationContextCommands(this.#responseCommand)

            return new InvocationContext(
                this.#runtimeContextId,
                this.#runtimeName,
                this.#connectionData,
                this.#responseCommand,
                true,
                this.#isStateless
            )
        } finally {
            for (let i = releases.length - 1; i >= 0; i--) {
                releases[i]()
            }
        }
    }

    /**
     * Process UpdateInvocationContext commands in the provided responseCommand payload.
     * Always removes ValueForUpdate items from response payload.
     * When stateful, also materializes referenced InvocationContexts to Reference commands.
     * @param {Command} responseCommand
     * @returns {Command}
     */
    #processUpdateInvocationContextCommands(responseCommand) {
        if (!responseCommand?.payload || responseCommand.payload.length === 0) {
            return responseCommand
        }

        /** @type {Command[]} */
        const commandsToUpdate = []
        for (const item of responseCommand.payload) {
            if (item instanceof Command && item.commandType === CommandType.ValueForUpdate) {
                commandsToUpdate.push(item)
            }
        }
        if (commandsToUpdate.length === 0) {
            return responseCommand
        }

        // create a copy of the payload to modify
        const updatedPayload = Array.from(responseCommand.payload)

        for (const cmd of commandsToUpdate) {
            if (!this.#isStateless) {
                const cmdPayload = cmd.payload
                if (cmdPayload && cmdPayload.length >= 2) {
                    const contextGuid = this.#getStringPayloadValue(cmdPayload[0])
                    const instanceGuid = this.#getStringPayloadValue(cmdPayload[1])
                    if (contextGuid && instanceGuid) {
                        const invCtx = InvocationContext.#claimRegisteredContext(contextGuid)
                        if (invCtx) {
                            invCtx.#currentCommand = new Command(invCtx.#runtimeName, CommandType.Reference, [
                                instanceGuid,
                            ])
                            invCtx.#isExecuted = true
                            InvocationContext._materializedReferences.set(contextGuid, invCtx.#currentCommand)
                        }
                    }
                }
            }
            // remove ValueForUpdate command from payload
            const idx = updatedPayload.indexOf(cmd)
            if (idx >= 0) updatedPayload.splice(idx, 1)
        }

        return new Command(responseCommand.runtimeName, responseCommand.commandType, updatedPayload)
    }

    /**
     * @param {Command} command
     * @returns {Command}
     */
    #materializeUpdatedReferences(command) {
        const materializedReference = this.#tryGetMaterializedReference(command)
        if (materializedReference) {
            return materializedReference
        }

        if (!command.payload || command.payload.length === 0) {
            return command
        }

        let changed = false
        const updatedPayload = command.payload.map((/** @type {unknown} */ item) => {
            if (item instanceof Command) {
                const updated = this.#materializeUpdatedReferences(item)
                if (updated !== item) changed = true
                return updated
            }
            return item
        })

        if (!changed) {
            return command
        }

        return new Command(command.runtimeName, command.commandType, updatedPayload)
    }

    /**
     * @param {Command} command
     * @returns {InvocationContext[]}
     */
    #getReferencedMaterializationContexts(command) {
        /** @type {Map<string, InvocationContext>} */
        const contexts = new Map()
        this.#collectReferencedMaterializationContexts(command, contexts)
        return Array.from(contexts.entries())
            .sort(([left], [right]) => left.localeCompare(right))
            .map(([, ctx]) => ctx)
    }

    /**
     * @param {Command} command
     * @param {Map<string, InvocationContext>} contexts
     */
    #collectReferencedMaterializationContexts(command, contexts) {
        if (
            command.commandType === CommandType.RegisterForUpdate &&
            command.payload &&
            command.payload.length >= 2
        ) {
            const contextGuid = this.#getStringPayloadValue(command.payload[1])
            if (contextGuid) {
                const invCtx = InvocationContext._invocationContexts.get(contextGuid)
                if (invCtx) {
                    contexts.set(contextGuid, invCtx)
                }
            }
        }

        if (!command.payload || command.payload.length === 0) {
            return
        }

        for (const item of command.payload) {
            if (item instanceof Command) {
                this.#collectReferencedMaterializationContexts(item, contexts)
            }
        }
    }

    /**
     * @param {Command} command
     * @returns {Command | null}
     */
    #tryGetMaterializedReference(command) {
        if (command.commandType !== CommandType.RegisterForUpdate || !command.payload || command.payload.length < 2) {
            return null
        }

        const contextGuid = this.#getStringPayloadValue(command.payload[1])
        if (!contextGuid) {
            return null
        }

        const invCtx = InvocationContext._invocationContexts.get(contextGuid)
        if (invCtx && invCtx.#isExecuted && invCtx.#currentCommand?.commandType === CommandType.Reference) {
            InvocationContext._materializedReferences.set(contextGuid, invCtx.#currentCommand)
            return invCtx.#currentCommand
        }

        return InvocationContext._materializedReferences.get(contextGuid) ?? null
    }

    /**
     * @param {unknown} argument
     * @returns {string}
     */
    #getStringPayloadValue(argument) {
        if (argument instanceof Command && argument.commandType === CommandType.Value) {
            const rawValue = argument.payload?.length ? argument.payload[0] : null
            return String(rawValue ?? '')
        }

        return String(argument ?? '')
    }

    /**
     * Atomically claim a registered context from the shared registry (TryRemove equivalent).
     * @param {string} contextGuid
     * @returns {InvocationContext | null}
     */
    static #claimRegisteredContext(contextGuid) {
        return InvocationContext.#withRegistryLock(() => {
            const invCtx = InvocationContext._invocationContexts.get(contextGuid)
            if (!invCtx) {
                return null
            }
            if (!InvocationContext._invocationContexts.delete(contextGuid)) {
                return null
            }
            return invCtx
        })
    }

    /**
     * @template T
     * @param {() => T} fn
     * @returns {T}
     */
    static #withRegistryLock(fn) {
        if (InvocationContext.#registryLock.locked) {
            throw new Error('InvocationContext registry lock re-entered')
        }
        InvocationContext.#registryLock.locked = true
        try {
            return fn()
        } finally {
            InvocationContext.#registryLock.locked = false
        }
    }

    /**
     * Invokes a static method on the target runtime.
     * @param {string} methodName - The name of the method to invoke.
     * @param {...any} args - Method arguments.
     * @returns {InvocationContext} A new InvocationContext instance that wraps the command to invoke the static method.
     * @see [Hypertube Guides](https://www.hypertube.dev/guides/v2/javascript/calling-methods/invoking-static-method)
     * @method
     */
    invokeStaticMethod(methodName, ...args) {
        let localCommand = new Command(this.#runtimeName, CommandType.InvokeStaticMethod, [
            methodName,
            ...args,
        ])
        if (this.#isStateless) {
            let localInvCtx = this.#createInstanceContext(localCommand)
            return localInvCtx.#passByValue()
        }
        return this.#createInstanceContext(localCommand)
    }

    #passByValue() {
        let localCommand = new Command(this.#runtimeName, CommandType.PassByValue)
        return this.#createInstanceContext(localCommand)
    }

    /**
     * Retrieves the value of a static field from the target runtime.
     * @param {string} fieldName - The name of the field to get.
     * @returns {InvocationContext} A new InvocationContext instance that wraps the command to get the static field.
     * @see [Hypertube Guides](https://www.hypertube.dev/guides/v2/javascript/fields-and-properties/getting-and-setting-values-for-static-fields-and-properties)
     * @method
     */
    getStaticField(fieldName) {
        let localCommand = new Command(this.#runtimeName, CommandType.GetStaticField, [fieldName])
        return this.#createInstanceContext(localCommand)
    }

    /**
     * Sets the value of a static field in the target runtime.
     * @param {string} fieldName - The name of the field to set.
     * @param {any} value - The new value of the field.
     * @returns {InvocationContext} A new InvocationContext instance that wraps the command to set the static field.
     * @see [Hypertube Guides](https://www.hypertube.dev/guides/v2/javascript/fields-and-properties/getting-and-setting-values-for-static-fields-and-properties)
     * @method
     */
    setStaticField(fieldName, value) {
        let localCommand = new Command(this.#runtimeName, CommandType.SetStaticField, [fieldName, value])
        return this.#createInstanceContext(localCommand)
    }

    /**
     * Creates a new instance of a class in the target runtime.
     * Adds the newly created context to the static invocation contexts map and
     * includes the context GUID as the first argument of CreateClassInstance command payload.
     * @param {...any} args - The arguments to pass to the class constructor
     * @returns {InvocationContext} A new InvocationContext instance that wraps the command to create the instance.
     * @method
     */
    createInstance(...args) {
        const localCommand = new Command(this.#runtimeName, CommandType.CreateClassInstance, [...args])
        const createInstanceInvCtx = this.#createInstanceContext(localCommand)
        return createInstanceInvCtx.#registerForUpdate()
    }

    /**
     * Registers the current InvocationContext for updates.
     * @returns {InvocationContext}
     */
    #registerForUpdate() {
        this.#currentCommand = this.#buildCommand(
            new Command(this.#runtimeName, CommandType.RegisterForUpdate, [this.getGuid()])
        )
        InvocationContext.#withRegistryLock(() => {
            InvocationContext._invocationContexts.set(this.getGuid(), this)
            InvocationContext._materializedReferences.delete(this.getGuid())
        })
        return this
    }

    /**
     * Retrieves the value of an instance field from the target runtime.
     * @param {string} fieldName - The name of the field to get.
     * @returns {InvocationContext} A new InvocationContext instance that wraps the command to get the instance field.
     * @see [Hypertube Guides](https://www.hypertube.dev/guides/v2/javascript/fields-and-properties/getting-and-setting-values-for-instance-fields-and-properties)
     * @method
     */
    getInstanceField(fieldName) {
        if (this.#isStateless) {
            const value = GetInstanceFieldHelper.getFieldValue(this.#currentCommand, fieldName)
            let returnCommand
            if (TypesHandler.isPrimitiveOrNullOrUndefined(value)) {
                returnCommand = new Command(this.#runtimeName, CommandType.Value, [value])
            } else if (value instanceof Command) {
                returnCommand = value
            } else {
                throw new Error(
                    `Unsupported type for stateless getInstanceField: ${value?.constructor?.name ?? typeof value}`
                )
            }

            return new InvocationContext(
                this.#runtimeContextId,
                this.#runtimeName,
                this.#connectionData,
                returnCommand,
                false,
                this.#isStateless
            )
        }

        let localCommand = new Command(this.#runtimeName, CommandType.GetInstanceField, [fieldName])
        return this.#createInstanceContext(localCommand)
    }

    /**
     * Sets the value of an instance field in the target runtime.
     * @param {string} fieldName - The name of the field to set.
     * @param {any} value - The new value of the field.
     * @returns {InvocationContext} A new InvocationContext instance that wraps the command to set the instance field.
     * @see [Hypertube Guides](https://www.hypertube.dev/guides/v2/javascript/fields-and-properties/getting-and-setting-values-for-instance-fields-and-properties)
     * @method
     */
    setInstanceField(fieldName, value) {
        let localCommand = new Command(this.#runtimeName, CommandType.SetInstanceField, [fieldName, value])
        const newCommand = this.#buildCommand(localCommand)
        if (this.#isStateless) {
            this.#currentCommand = newCommand
            return this
        }
        return new InvocationContext(
            this.#runtimeContextId,
            this.#runtimeName,
            this.#connectionData,
            newCommand,
            this.#isExecuted,
            this.#isStateless
        )
    }

    /**
     * Invokes an instance method on the target runtime.
     * @param {string} methodName - The name of the method to invoke.
     * @param {...any} args - Method arguments.
     * @returns {InvocationContext} A new InvocationContext instance that wraps the command to invoke the instance method.
     * @see [Hypertube Guides](https://www.hypertube.dev/guides/v2/javascript/calling-methods/invoking-instance-method)
     * @method
     */
    invokeInstanceMethod(methodName, ...args) {
        let localCommand = new Command(this.#runtimeName, CommandType.InvokeInstanceMethod, [
            methodName,
            ...args,
        ])
        return this.#createInstanceContext(localCommand)
    }

    /**
     * Retrieves the value at a specific index in an array from the target runtime.
     * @param {...any} indexes - the arguments to pass to the array getter. The first argument should be the index.
     * @returns {InvocationContext} A new InvocationContext instance that wraps the command to get the index.
     * @see [Hypertube Guides](https://www.hypertube.dev/guides/v2/javascript/arrays-and-collections/one-dimensional-arrays)
     * @method
     */
    getIndex(...indexes) {
        let localCommand = new Command(this.#runtimeName, CommandType.ArrayGetItem, indexes)
        return this.#createInstanceContext(localCommand)
    }

    /**
     * Sets the value at a specific index in an array in the target runtime.
     * @param {number[]} indexes - The index to set the value at.
     * @param {any} value - The value to set at the index.
     * @returns {InvocationContext} A new InvocationContext instance that wraps the command to set the index.
     * @see [Hypertube Guides](https://www.hypertube.dev/guides/v2/javascript/arrays-and-collections/one-dimensional-arrays)
     * @method
     */
    setIndex(indexes, value) {
        let localCommand = new Command(this.#runtimeName, CommandType.ArraySetItem, [indexes, value])
        return this.#createInstanceContext(localCommand)
    }

    /**
     * Retrieves the size of an array from the target runtime.
     * @returns {InvocationContext} A new InvocationContext instance that wraps the command to get the size.
     * @see [Hypertube Guides](https://www.hypertube.dev/guides/v2/javascript/arrays-and-collections/one-dimensional-arrays)
     * @method
     */
    getSize() {
        let localCommand = new Command(this.#runtimeName, CommandType.ArrayGetSize, [])
        return this.#createInstanceContext(localCommand)
    }

    /**
     * Retrieves the rank of an array from the target runtime.
     * @returns {InvocationContext} A new InvocationContext instance that wraps the command to get the rank.
     * @see [Hypertube Guides](https://www.hypertube.dev/guides/v2/javascript/arrays-and-collections/one-dimensional-arrays)
     * @method
     */
    getRank() {
        let localCommand = new Command(this.#runtimeName, CommandType.ArrayGetRank, [])
        return this.#createInstanceContext(localCommand)
    }

    /**
     * Invokes a generic static method on the target runtime.
     * @param {string} methodName - The name of the method to invoke.
     * @param {...any} args - Method arguments.
     * @returns {InvocationContext} A new InvocationContext instance that wraps the command to invoke the generic static method.
     * @see [Hypertube Guides](https://www.hypertube.dev/guides/v2/javascript/generics/calling-generic-static-method)
     * @method
     */
    invokeGenericStaticMethod(methodName, ...args) {
        let localCommand = new Command(this.#runtimeName, CommandType.InvokeGenericStaticMethod, [
            methodName,
            ...args,
        ])
        return this.#createInstanceContext(localCommand)
    }

    /**
     * Invokes a generic method on the target runtime.
     * @param {string} methodName - The name of the method to invoke.
     * @param {...any} args - Method arguments.
     * @returns {InvocationContext} A new InvocationContext instance that wraps the command to invoke the generic method.
     * @see [Hypertube Guides](https://www.hypertube.dev/guides/v2/javascript/generics/calling-generic-instance-method)
     * @method
     */
    invokeGenericMethod(methodName, ...args) {
        let localCommand = new Command(this.#runtimeName, CommandType.InvokeGenericMethod, [
            methodName,
            ...args,
        ])
        return this.#createInstanceContext(localCommand)
    }

    /**
     * Retrieves the name of an enum from the target runtime.
     * @returns {InvocationContext} A new InvocationContext instance that wraps the command to get the enum name.
     * @see [Hypertube Guides](https://www.hypertube.dev/guides/v2/javascript/enums/using-enum-type)
     * @method
     */
    getEnumName() {
        let localCommand = new Command(this.#runtimeName, CommandType.GetEnumName, [])
        return this.#createInstanceContext(localCommand)
    }

    /**
     * Retrieves the value of an enum from the target runtime.
     * @returns {InvocationContext} A new InvocationContext instance that wraps the command to get the enum value.
     * @see [Hypertube Guides](https://www.hypertube.dev/guides/v2/javascript/enums/using-enum-type)
     * @method
     */
    getEnumValue() {
        let localCommand = new Command(this.#runtimeName, CommandType.GetEnumValue, [])
        return this.#createInstanceContext(localCommand)
    }

    /**
     * Retrieves the value of a reference from the target runtime.
     * @returns {InvocationContext} A new InvocationContext instance that wraps the command to get the ref value.
     * @see [Hypertube Guides](https://www.hypertube.dev/guides/v2/javascript/methods-arguments/passing-arguments-by-reference-with-ref-keyword)
     * @method
     */
    getRefValue() {
        let localCommand = new Command(this.#runtimeName, CommandType.GetRefValue, [])
        return this.#createInstanceContext(localCommand)
    }

    /**
     * Creates a null object of a specific type on the target runtime.
     *
     * @returns {InvocationContext} An InvocationContext instance with the command to create a null object.
     * @see [Hypertube Guides](https://www.hypertube.dev/guides/v2/javascript/null-handling/create-null-object)
     * @method
     */
    createNull() {
        let localCommand = new Command(this.#runtimeName, CommandType.CreateNull, [])
        return this.#createInstanceContext(localCommand)
    }

    /**
     * Creates a null object of a specific type on the target runtime.
     * @param {string} methodName - The name of the method to invoke.
     * @param {...any} args - Method arguments.
     * @returns {InvocationContext} An InvocationContext instance with the command to create a null object.
     * TODO: connect documentation page url
     * @see [Hypertube Guides](https://www.hypertube.dev/guides/)
     * @method
     */
    getStaticMethodAsDelegate(methodName, ...args) {
        const localCommand = new Command(this.#runtimeName, CommandType.GetStaticMethodAsDelegate, [
            methodName,
            ...args,
        ])
        return this.#createInstanceContext(localCommand)
    }

    /**
     * Creates a null object of a specific type on the target runtime.
     * @param {string} methodName - The name of the method to invoke.
     * @param {...any} args - Method arguments.
     * @returns {InvocationContext} An InvocationContext instance with the command to create a null object.
     * TODO: connect documentation page url
     * @see [Hypertube Guides](https://www.hypertube.dev/guides/)
     * @method
     */
    getInstanceMethodAsDelegate(methodName, ...args) {
        const localCommand = new Command(this.#runtimeName, CommandType.GetInstanceMethodAsDelegate, [
            methodName,
            ...args,
        ])
        return this.#createInstanceContext(localCommand)
    }

    /**
     * Retrieves the type of the object from the target runtime.
     * @returns {Promise<string | null>} The type of the object.
     * @see [Hypertube Guides](https://www.hypertube.dev/guides/v2/javascript/type-handling/getting-object-type)
     * @method
     */
    async getResultType() {
        if (this.#isStateless) {
            return GetInstanceFieldHelper.getResultType(this.#currentCommand)
        }

        if (
            this.#currentCommand != null &&
            this.#currentCommand.commandType === CommandType.ComplexValueType
        ) {
            return String(this.#currentCommand.payload[0])
        }

        const localCommand = new Command(this.#runtimeName, CommandType.GetResultType, [])
        const invocationContext = new InvocationContext(
            this.#runtimeContextId,
            this.#runtimeName,
            this.#connectionData,
            this.#buildCommand(localCommand)
        )
        const execCtx = await invocationContext.execute()
        return String(execCtx.getValue())
    }

    /**
     * Retrieves the name of the runtime where the command is executed.
     * @returns {number} The name of the runtime.
     * @see [Hypertube Guides](https://www.hypertube.dev/guides/v2/javascript/runtime-name)
     * @method
     */
    getRuntimeName() {
        return this.#runtimeName
    }

    /**
     * Retrieves an array from the target runtime.
     * @async
     * @returns {Promise<any[]>}
     * @method
     */
    /**
     * Retrieves an array from the target runtime.
     * @returns {Promise<any[]>} The retrieved array.
     * @method
     */
    async retrieveArray() {
        /** @type {InvocationContext} */
        let arrayInvCtx = this
        if (!this.#isStateless) {
            const retrieveArrayCommand = new Command(this.#runtimeName, CommandType.RetrieveArray)
            const localInvCtx = new InvocationContext(
                this.#runtimeContextId,
                this.#runtimeName,
                this.#connectionData,
                this.#buildCommand(retrieveArrayCommand)
            )
            arrayInvCtx = await localInvCtx.execute()
        }

        return this.#materializeArrayPayload(arrayInvCtx.#currentCommand?.payload ?? [])
    }

    /**
     * @param {any[]} payload
     * @returns {any[]}
     */
    #materializeArrayPayload(payload) {
        if (payload.length === 0) {
            return []
        }

        const isCommandPayloadItem = (/** @type {any} */ item) =>
            item instanceof Command ||
            (item &&
                typeof item === 'object' &&
                typeof item.commandType !== 'undefined' &&
                Array.isArray(item.payload))

        const getCommandType = (/** @type {any} */ item) =>
            item instanceof Command ? item.commandType : item?.commandType

        if (isCommandPayloadItem(payload[0]) && getCommandType(payload[0]) !== CommandType.Array) {
            return payload.map(
                (/** @type {any} */ item) =>
                    new InvocationContext(
                        this.#runtimeContextId,
                        this.#runtimeName,
                        this.#connectionData,
                        item,
                        this.#isExecuted,
                        this.#isStateless
                    )
            )
        }

        return payload.map((/** @type {any} */ item) => {
            if (isCommandPayloadItem(item) && getCommandType(item) === CommandType.Array) {
                return this.#materializeArrayPayload(item.payload ?? [])
            }
            return item
        })
    }

    /**
     * Returns the primitive value from the target runtime. This could be any primitive type in JavaScript,
     * such as int, boolean, byte, char, long, double, float, etc.
     * @returns {any} The value of the current command.
     * @see [Hypertube Guides](https://www.hypertube.dev/guides/v2/javascript/foundations/execute-method)
     * @method
     */
    getValue() {
        if (this.#currentCommand?.commandType === CommandType.Value) {
            if (TypesHandler.isPrimitiveOrNullOrUndefined(this.#currentCommand?.payload[0])) {
                return this.#currentCommand?.payload[0]
            }
        }
        return this
    }

    /**
     * @param {Command} command
     * @returns {Command | null}
     */
    #buildCommand(command) {
        if (!command || !command.payload) {
            return this.#currentCommand
        }
        for (let i = 0; i < command.payload.length; i++) {
            command.payload[i] = this.#encapsulatePayloadItem(command.payload[i])
        }
        return command.prependArgToPayload(this.#currentCommand)
    }

    /**
     * @param {unknown} payloadItem
     * @returns {Command|null}
     */
    #encapsulatePayloadItem(payloadItem) {
        if (payloadItem instanceof Command) {
            if (
                payloadItem.commandType === CommandType.Value ||
                payloadItem.commandType === CommandType.Array
            ) {
                return payloadItem
            }

            for (let i = 0; i < payloadItem.payload.length; i++) {
                payloadItem.payload[i] = this.#encapsulatePayloadItem(payloadItem.payload[i])
            }
            return payloadItem
        } else if (payloadItem instanceof InvocationContext) {
            return payloadItem.getCurrentCommand()
        } else if (payloadItem instanceof Array) {
            const copiedArray = payloadItem.map((item) => this.#encapsulatePayloadItem(item))
            return new Command(this.#runtimeName, CommandType.Array, copiedArray)
        } else if (typeof payloadItem === 'function') {
            let newArray = new Array(payloadItem.length + 1)
            for (let i = 0; i < newArray.length; i++) {
                newArray[i] = typeof Object
            }
            const args = [delegatesCacheInstance.addDelegate(payloadItem), RuntimeName.Nodejs]
            args.push(...newArray)
            return new Command(this.#runtimeName, CommandType.PassDelegate, args)
        } else if (TypesHandler.isPrimitiveOrNullOrUndefined(payloadItem)) {
            return new Command(this.#runtimeName, CommandType.Value, [payloadItem])
        } else {
            const complexCommand = ComplexTypeResolver.convertComplexTypeToCommand(
                this.#runtimeName,
                payloadItem
            )
            if (complexCommand) return complexCommand
            throw Error(
                'Unsupported payload item type: ' +
                    (payloadItem?.constructor?.name || typeof payloadItem) +
                    ' for payload item: ' +
                    payloadItem
            )
        }
    }
}

export { InvocationContext }
